test('Load more appends only the next batch with the frozen execution options', async () => {
    const current = execution({ responses: [batch([0, 1], 0, true), batch([2, 3], 2, false)] });
    current.controller.submit();
    await settle();
    assert.equal(typeof current.controller.loadMore, 'function');
    const firstQuery = current.controls.query.value;
    current.controls.query.value = 'SELECT ?different WHERE {}';
    current.controls.infer.value = 'false';
    current.controls['query-timeout'].value = '1';
    current.form.setAttribute('action', '/repositories/different/query');
    current.controller.loadMore();
    await settle();
    assert.equal(current.requests.length, 2);
    assert.equal(current.requests[1].url, current.requests[0].url);
    const body = current.requests[1].init.body;
    assert.equal(body.get('query'), firstQuery);
    assert.equal(body.get('infer'), 'true');
    assert.equal(body.get('query-timeout'), '60');
    assert.equal(body.get('batch-offset'), '2');
    assert.notEqual(body.get('query-request-id'), current.requests[0].init.body.get('query-request-id'));
    assert.equal(current.workers.length, 1);
    assert.deepEqual(current.workers[0].rows.map(row => row[0].value), ['0', '1', '2', '3']);
    assert.equal(current.target.querySelector('.query-result-load-more').hidden, true);
    current.controller.dispose();
});

test('failed append rolls back its partial tail and retries the same offset without duplicates', async () => {
    const failed = batch([2], 2, true).slice(0, -1);
    failed.push({ type: 'error', code: 'timeout', message: 'Timed out while appending.' });
    const current = execution({ responses: [batch([0, 1], 0, true), failed, batch([2, 3], 2, false)] });
    current.controller.submit();
    await settle();
    assert.equal(typeof current.controller.loadMore, 'function');
    current.controller.loadMore();
    await settle();
    assert.deepEqual(current.workers[0].rows.map(row => row[0].value), ['0', '1']);
    assert.match(current.target.querySelector('.query-result-status').textContent, /2.*retained|retained.*2/i);
    assert.equal(current.target.querySelector('.query-result-load-more').hidden, false);
    assert.equal(current.target.querySelector('.query-result-load-more').disabled, false);
    current.controller.loadMore();
    await settle();
    assert.equal(current.requests[2].init.body.get('batch-offset'), '2');
    assert.deepEqual(current.workers[0].rows.map(row => row[0].value), ['0', '1', '2', '3']);
    current.controller.dispose();
});

