test('logical scroll coordinates retain first middle and last windows beyond browser pixel limits', () => {
    const { api } = loadApi();
    assert.equal(typeof api.ResultScrollCoordinates, 'function');
    const coordinates = new api.ResultScrollCoordinates(1000000);
    coordinates.update(100000000, 500);
    assert.equal(coordinates.physicalHeight, 1000000);
    assert.equal(coordinates.logicalOffset(0), 0);
    assert.equal(coordinates.logicalOffset(999500), 99999500);
    const middle = coordinates.physicalOffset(50000000);
    assert.ok(Math.abs(coordinates.logicalOffset(middle) - 50000000) < 0.01);
    const spacers = coordinates.spacers(49999800, 1200, middle);
    assert.ok(Math.abs(spacers.top + 1200 + spacers.bottom - coordinates.physicalHeight) < 0.01);
    assert.ok(Math.abs(middle - spacers.top - 200) < 0.01,
        'visible rows keep their real height while only offscreen coordinates are compressed');
});

test('compressed coordinates keep the rows next to the start and the end of the result in place', () => {
    const { api } = loadApi();
    const coordinates = new api.ResultScrollCoordinates(1000000);
    const logicalHeight = 100000000;
    const view = 800;
    coordinates.update(logicalHeight, view);
    const maximum = coordinates.maximumOffset;
    // The window holds whole rows ahead of the view: up to 2000 px above its top and below its bottom.
    for (const logical of [300, 1200, 2400, 4800, maximum / 2, maximum - 4800, maximum - 1200, maximum - 300]) {
        const physical = coordinates.physicalOffset(logical);
        const above = Math.min(2000, logical);
        const windowHeight = above + Math.min(view + 2000, logicalHeight - logical);
        const spacers = coordinates.spacers(logical - above, windowHeight, physical, logical);
        assert.ok(Math.abs(spacers.top + above - physical) < 0.01,
            `the row at ${logical} px must be at the top of the view (scrollTop ${physical}); it is ${spacers.top + above - physical} px off`);
        assert.ok(Math.abs(spacers.top + windowHeight + spacers.bottom - coordinates.physicalHeight) < 0.01);
        assert.ok(Math.abs(coordinates.logicalOffset(physical) - logical) < 0.01, `${logical} px must map back to itself`);
    }
    let previous = -1;
    for (let physical = 0; physical <= coordinates.physicalHeight - view; physical += 997) {
        const logical = coordinates.logicalOffset(physical);
        assert.ok(logical > previous, 'logical offsets grow with the scroll bar');
        previous = logical;
    }
});

