test('progressive row writes coalesce visible rendering rather than rereading for every wire record', async () => {
    const { api, document, window } = loadApi();
    const frames = [];
    window.requestAnimationFrame = callback => { frames.push(callback); };
    const target = document.createElement('section');
    document.body.appendChild(target);
    let count = 0;
    let reads = 0;
    const renderer = new api.QueryResultRenderer(target, {
        batched: true, requestedLimit: 3200, rowStore: {
            async append(rows) { count += rows.length; return count; },
            async read(start, size) { reads++; return Array.from({ length: size }, () => [null]); },
            async count() { return count; }, async truncate(next) { count = next; return count; }, async dispose() {}
        }
    });
    renderer.beginBatch(0);
    await renderer.accept({ type: 'head', version: 1 });
    await renderer.accept({ type: 'view', id: 'tuple' });
    await renderer.accept({ type: 'vars', values: ['value'] });
    for (let index = 0; index < 100; index++) {
        await renderer.accept({ type: 'rows', values: Array.from({ length: 32 }, () => [null]) });
    }
    await renderer.accept({ type: 'end', metadata: {
        'result-offset': 0, 'result-limit': 3200, 'result-batch-count': 3200,
        'result-has-more': false, 'result-next-offset': 3200
    } });
    assert.equal(count, 3200);
    assert.ok(reads <= 3, `received records must not each reread the visible window; saw ${reads} reads`);
    assert.ok(frames.length <= 1, 'pending rendering is coalesced into one animation frame');
    renderer.dispose();
});

// WebKit can report a zero or negative scrollHeight for the 1px capacity probe (legacy scrollbars wider than the probe,
// or layout units saturating past the engine's pixel limit) while the child still renders. A capacity probe must never
// hand that value on: the Explore page's result tables threw "A positive physical scroll capacity is required."
for (const [name, probeScrollHeight] of [
    ['zero', () => 0],
    ['negative', () => -14],
    ['wrapping past the cap', requested => requested > 40000 ? -2147483648 + requested : requested]
]) {
    test(`a ${name} probe scrollHeight still yields a positive scroll capacity`, () => {
        const { api, document } = loadApi();
        const createElement = document.createElement.bind(document);
        document.createElement = tag => {
            const element = createElement(tag);
            element.getBoundingClientRect = () => {
                const requested = parseFloat(element.style.height) || 0;
                return { top: 0, left: 0, width: 1, height: requested };
            };
            if (tag === 'div') Object.defineProperty(element, 'scrollHeight', { get() {
                if (this.style.overflow !== 'scroll' || !this.children.length) return 0;
                const content = this.children[0];
                const target = content.tagName === 'TABLE' ? content.children[0].children[0].children[0] : content;
                return probeScrollHeight(parseFloat(target.style.height) || 0);
            } });
            return element;
        };
        const target = document.createElement('section');
        document.body.appendChild(target);
        const table = new api.ResultTable(target, {
            rowCount: () => 0, variables: () => ['s'], read: async () => [], namespaces: () => []
        });
        for (const capacity of [table.tableScrollCapacity, table.recordScrollCapacity]) {
            assert.ok(isFinite(capacity) && capacity > 0, `scroll capacity must be positive; got ${capacity}`);
        }
        if (name === 'wrapping past the cap') {
            assert.ok(table.tableScrollCapacity <= 40000 && table.tableScrollCapacity >= 32768,
                `only verified probe heights may become the capacity; got ${table.tableScrollCapacity}`);
        }
        table.dispose();
    });
}

// Firefox lays the rows of a real result box out a few hundred pixels short of what the 1px probe scrolls, which left
// the last rows of a compressed result out of reach.
test('the scroll capacity keeps headroom below the height the browser clamps scrolling to', () => {
    const { api, document } = loadApi();
    const clamp = 17895698;
    const createElement = document.createElement.bind(document);
    document.createElement = tag => {
        const element = createElement(tag);
        element.getBoundingClientRect = () => ({ top: 0, left: 0, width: 1,
            height: Math.min(clamp, parseFloat(element.style.height) || 0) });
        if (tag === 'div') Object.defineProperty(element, 'scrollHeight', { get() {
            if (this.style.overflow !== 'scroll' || !this.children.length) return 0;
            const content = this.children[0];
            const target = content.tagName === 'TABLE' ? content.children[0].children[0].children[0] : content;
            return Math.min(clamp, parseFloat(target.style.height) || 0);
        } });
        return element;
    };
    const target = document.createElement('section');
    document.body.appendChild(target);
    const table = new api.ResultTable(target, {
        rowCount: () => 0, variables: () => ['s'], read: async () => [], namespaces: () => []
    });
    for (const capacity of [table.tableScrollCapacity, table.recordScrollCapacity]) {
        assert.ok(capacity <= clamp - 1000 && capacity > clamp * 0.99,
            `the capacity must stay at least 1000 px below the ${clamp} px clamp; got ${capacity}`);
    }
    table.dispose();
});

for (const layout of ['table', 'records']) {
  for (const overflow of ['clamp', 'collapse']) {
    test(`${layout} ${overflow} scroll capacity keeps wheel and keyboard row access`, async () => {
        const { api, document } = loadApi();
        const createElement = document.createElement.bind(document);
        document.createElement = name => {
            const element = createElement(name);
            element.getBoundingClientRect = () => {
                const requested = parseFloat(element.style.height) || 0;
                return { top: 0, left: 0, width: 0,
                    height: overflow === 'collapse' && requested > 1000 ? 0 : Math.min(1000, requested) };
            };
            if (name === 'div') Object.defineProperty(element, 'scrollHeight', { get() {
                if (this.style.overflow !== 'scroll' || !this.children.length) return 0;
                const content = this.children[0];
                const target = content.tagName === 'TABLE' ? content.children[0].children[0].children[0] : content;
                const requested = parseFloat(target.style.height) || 0;
                return Math.max(1, overflow === 'collapse' && requested > 1000 ? 0 : Math.min(1000, requested));
            } });
            return element;
        };
        const target = document.createElement('section');
        document.body.appendChild(target);
        const rows = Array.from({ length: 3000 }, () => [null]);
        const reads = [];
        const renderer = new api.QueryResultRenderer(target, {
            initialLayout: layout, maxDomRows: 8, rowStore: {
                async append() { return rows.length; }, async read(start, count) {
                    reads.push([start, count]);
                    return rows.slice(start, start + count);
                },
                async count() { return rows.length; }, async truncate() {}, async dispose() {}
            }
        });
        const scrollport = layout === 'table' ? renderer.tableWrap : target.querySelector('.query-result-records');
        scrollport.clientHeight = 96;
        for (const record of batch([], 0, false).slice(0, 4)) await renderer.accept(record);
        await renderer.accept({ type: 'rows', values: rows });
        await renderer.accept({ type: 'end', metadata: { 'total-result-count': rows.length } });
        assert.equal(reads[reads.length - 1][0], 0, 'the initial window should start at the first loaded row');
        const spacers = scrollport.querySelectorAll('[data-query-spacer]');
        assert.ok(spacers.reduce((sum, spacer) => sum + (parseFloat(spacer.style.height) || 0), 0) > 0,
            'hidden loaded rows need usable physical scroll extent after oversized blocks collapse');
        const wheel = scrollport.trigger('wheel', { deltaY: 20000, deltaMode: 0 });
        assert.equal(wheel.defaultPrevented, true, 'wheel steps must retain natural logical distances above the pixel cap');
        await settle();
        const beforeWheel = reads[reads.length - 1];
        assert.ok(beforeWheel[0] >= 800 && beforeWheel[0] < 1200,
            `wheel scrolling should request a middle virtual window; got ${beforeWheel}`);
        const nextWheel = scrollport.trigger('wheel', { deltaY: 240, deltaMode: 0 });
        assert.equal(nextWheel.defaultPrevented, true);
        await settle();
        const afterWheel = reads[reads.length - 1];
        assert.ok(afterWheel[0] > beforeWheel[0],
            'wheel scrolling should advance the virtualized window through loaded rows');
        const end = scrollport.trigger('keydown', { key: 'End' });
        assert.equal(end.defaultPrevented, true, 'End should move the native result scrollport to its loaded tail');
        await settle();
        const lastWindow = reads[reads.length - 1];
        assert.ok(lastWindow[0] <= 2999 && lastWindow[0] + lastWindow[1] > 2999,
            'End should request a virtual window containing the last loaded row');
        const home = scrollport.trigger('keydown', { key: 'Home' });
        assert.equal(home.defaultPrevented, true, 'Home should return to the start of the loaded result');
        await settle();
        assert.equal(reads[reads.length - 1][0], 0, 'Home should request the first loaded row window');
        renderer.dispose();
    });
  }
}

/**
 * A rendered result of 3000 rows of 24 px whose scroll element holds at most about 1000 px, so it scrolls in compressed
 * coordinates; holdReads() keeps the next row reads pending until release() answers them, like a row store that reads
 * spilled rows back from browser storage.
 */
async function compressedResult(layout) {
    const { api, document } = loadApi();
    const createElement = document.createElement.bind(document);
    document.createElement = name => {
        const element = createElement(name);
        element.getBoundingClientRect = () => {
            const requested = parseFloat(element.style.height) || 0;
            return { top: 0, left: 0, width: 0, height: Math.min(1000, requested) };
        };
        if (name === 'div') Object.defineProperty(element, 'scrollHeight', { get() {
            if (this.style.overflow !== 'scroll' || !this.children.length) return 0;
            const content = this.children[0];
            const target = content.tagName === 'TABLE' ? content.children[0].children[0].children[0] : content;
            return Math.max(1, Math.min(1000, parseFloat(target.style.height) || 0));
        } });
        return element;
    };
    const target = document.createElement('section');
    document.body.appendChild(target);
    const rows = Array.from({ length: 3000 }, () => [null]);
    const reads = [];
    const pending = [];
    let holding = false;
    const renderer = new api.QueryResultRenderer(target, {
        initialLayout: layout, maxDomRows: 8, rowStore: {
            async append() { return rows.length; },
            read(start, count) {
                reads.push([start, count]);
                const answer = () => rows.slice(start, start + count);
                return holding ? new Promise(resolve => pending.push(() => resolve(answer()))) : Promise.resolve(answer());
            },
            async count() { return rows.length; }, async truncate() {}, async dispose() {}
        }
    });
    const scrollport = layout === 'table' ? renderer.tableWrap : target.querySelector('.query-result-records');
    scrollport.clientHeight = 96;
    for (const record of batch([], 0, false).slice(0, 4)) await renderer.accept(record);
    await renderer.accept({ type: 'rows', values: rows });
    await renderer.accept({ type: 'end', metadata: { 'total-result-count': rows.length } });
    await settle();
    return {
        renderer, scrollport, reads,
        holdReads() { holding = true; },
        async release() {
            holding = false;
            while (pending.length) pending.shift()();
            await settle();
            await settle();
        },
        /** The row at the top of the view for a native scrollTop, from the box's scroll capacity and the 96 px view. */
        rowAtScrollTop(scrollTop) {
            const coordinates = new api.ResultScrollCoordinates(layout === 'table'
                ? renderer.tableScrollCapacity : renderer.resultTable.recordScrollCapacity);
            coordinates.update(rows.length * 24, 96);
            return Math.floor(coordinates.logicalOffset(scrollTop) / 24);
        }
    };
}

function windowContains(read, row) {
    return read[0] <= row && read[0] + read[1] > row;
}

for (const layout of ['table', 'records']) {
    test(`${layout} wheel steps taken while a compressed window read is pending all count`, async () => {
        const result = await compressedResult(layout);
        result.holdReads();
        const first = result.scrollport.trigger('wheel', { deltaY: 4800, deltaMode: 0 });
        assert.equal(first.defaultPrevented, true);
        // The window for the first step is being read when the second step arrives.
        await settle();
        const second = result.scrollport.trigger('wheel', { deltaY: 4800, deltaMode: 0 });
        assert.equal(second.defaultPrevented, true);
        await result.release();
        const last = result.reads[result.reads.length - 1];
        assert.ok(windowContains(last, 400),
            `two wheel steps of 4800 px over 24 px rows should show row 400; the last window read was ${last}`);
        result.renderer.dispose();
    });

    test(`${layout} a window read that ends after a native scroll does not scroll back`, async () => {
        const result = await compressedResult(layout);
        result.holdReads();
        result.scrollport.scrollTop = 300;
        result.scrollport.trigger('scroll');
        // The window for 300 px is being read when the scroll bar is dragged on to 600 px.
        await settle();
        result.scrollport.scrollTop = 600;
        await result.release();
        assert.ok(Math.abs(result.scrollport.scrollTop - 600) < 1,
            `the older window must not move the scroll bar back from 600 px; it is at ${result.scrollport.scrollTop}`);
        result.scrollport.trigger('scroll');
        await settle();
        const last = result.reads[result.reads.length - 1];
        const row = result.rowAtScrollTop(600);
        assert.ok(windowContains(last, row), `the rows at 600 px start at row ${row}; the last window read was ${last}`);
        result.renderer.dispose();
    });
}

for (const layout of ['table', 'records']) {
    // In compressed coordinates the browser's own Space scrolling moves the scroll bar by a view, which is many views of
    // rows; Space and Shift+Space page like PageDown and PageUp instead.
    test(`${layout} Space and Shift+Space page by one view in compressed results`, async () => {
        const result = await compressedResult(layout);
        result.scrollport.trigger('wheel', { deltaY: 30000, deltaMode: 0 });
        await settle();
        const start = result.reads[result.reads.length - 1][0];
        const down = result.scrollport.trigger('keydown', { key: ' ' });
        assert.equal(down.defaultPrevented, true, 'Space must not scroll the compressed scroll bar by a whole view');
        await settle();
        const afterDown = result.reads[result.reads.length - 1][0];
        assert.ok(Math.abs(afterDown - start - 4) <= 1,
            `Space should move one 96 px view (4 rows of 24 px); the window moved ${afterDown - start} rows`);
        const up = result.scrollport.trigger('keydown', { key: ' ', shiftKey: true });
        assert.equal(up.defaultPrevented, true);
        await settle();
        const afterUp = result.reads[result.reads.length - 1][0];
        assert.ok(Math.abs(afterUp - start) <= 1, `Shift+Space should move back one view; the window is at ${afterUp}`);
        result.renderer.dispose();
    });

    // A touch swipe scrolls natively (the browser keeps its momentum), so its distance is taken one to one rather than
    // through the compressed scroll bar's scale; when it settles the scroll bar is put back where the rows are.
    test(`${layout} a touch swipe moves compressed rows by the distance of the finger`, async () => {
        const result = await compressedResult(layout);
        result.scrollport.trigger('wheel', { deltaY: 30000, deltaMode: 0 });
        await settle();
        const start = result.reads[result.reads.length - 1][0];
        const committed = result.scrollport.scrollTop;
        result.scrollport.trigger('touchstart');
        result.scrollport.scrollTop = committed + 48;
        result.scrollport.trigger('scroll');
        await settle();
        const swiped = result.reads[result.reads.length - 1][0];
        assert.ok(Math.abs(swiped - start - 2) <= 1,
            `a 48 px swipe should move the rows 2 rows of 24 px; the window moved ${swiped - start} rows`);
        assert.equal(result.scrollport.scrollTop, committed + 48, 'the scroll position stays the browser\'s during a swipe');
        // The finger is lifted on the element it touched; the box comes to rest afterwards.
        result.scrollport.trigger('touchend');
        result.scrollport.trigger('scrollend');
        await settle();
        const settled = result.reads[result.reads.length - 1][0];
        assert.ok(Math.abs(settled - swiped) <= 1, `the rows stay in place when the swipe settles; they moved to ${settled}`);
        assert.ok(Math.abs(result.scrollport.scrollTop - committed) < 2,
            `the scroll bar returns to the compressed position of the rows; it is at ${result.scrollport.scrollTop}`);
        result.renderer.dispose();
    });
}

/** Sends a key from inside the rows (a focused link or button), bubbling up to the scroll box as in a browser. */
function keyFrom(element, key) {
    element.dispatchEvent({ type: 'keydown', key, bubbles: true, defaultPrevented: false,
        preventDefault() { this.defaultPrevented = true; } });
}

for (const layout of ['table', 'records']) {
    // A focused link inside the rows (reached with Tab) passes the scroll keys on to the box: the browser would scroll
    // the compressed scroll bar by them, many views of rows. Space still presses a focused button.
    test(`${layout} scroll keys from a focused link inside compressed rows page by the rows`, async () => {
        const result = await compressedResult(layout);
        result.scrollport.trigger('wheel', { deltaY: 30000, deltaMode: 0 });
        await settle();
        const start = result.reads[result.reads.length - 1][0];
        const row = result.scrollport.querySelector('[data-query-row-index], [data-query-record-index]');
        keyFrom(row, 'PageDown');
        await settle();
        const paged = result.reads[result.reads.length - 1][0];
        assert.ok(Math.abs(paged - start - 4) <= 1,
            `PageDown from a focused link should move one 96 px view (4 rows); the window moved ${paged - start} rows`);
        const visible = result.scrollport.querySelector('[data-query-row-index], [data-query-record-index]');
        const button = visible.ownerDocument.createElement('button');
        visible.appendChild(button);
        const reads = result.reads.length;
        keyFrom(button, ' ');
        await settle();
        assert.equal(result.reads.length, reads, 'Space on a focused button presses the button instead of scrolling');
        result.renderer.dispose();
    });
}
